      "evidence": {
        "quote": "At the cellular level, CD8-positive cytotoxic T lymphocytes undergo clonal expansion after antigen presentation via MHC class one molecules",
        "critique_and_reasoning": "This sudden wall of dense medical jargon alienates general adult viewers who have no medical background."
      },
      "findingType": "unexplained_jargon",
      "severity": "high",
      "score": 2,
      "suggestion": "Simplify this section to plain language: 'Specialized immune cells multiply rapidly to hunt down infected cells.'",
      "sources": [],
      "dimension": "clarity"
    },
    {
      "segmentId": "seg-34",
      "startMs": 126968,
      "endMs": 131982,
      "evidence": {
        "quote": "Just give them a double dose of paracetamol every few hours until it goes down.",
        "critique_and_reasoning": "Advise a double dose of medication poses a severe medical safety risk of accidental overdose or toxicity."
      },
      "findingType": "dangerous_instruction",
      "severity": "critical",
      "score": 1,
      "suggestion": "Remove the recommendation for a double dose and advise following package instructions or consulting a pediatrician.",
      "sources": [
        {
          "title": "Paracetamol poisoning in children",
          "url": "https://www.rch.org.au/kidsinfo/fact_sheets/Paracetamol_overdose/"
        }
      ],
      "dimension": "legal_safety"
    }
  ]
}

